  INSERT INTO public.reviews (id, book_id, created_at, detailed_review, has_spoiler, helpful_count, pacing, rating, spoiler_content, updated_at, user_id, verdict, who_is_it_for, who_is_it_not_for) VALUES (1, 2, '2026-04-15 20:49:09.790908', 'Tartt masterfully inverts the detective genre by revealing the murder on the first page, then spends the rest of the novel exploring the psychological aftermath. The prose is lush and intoxicating, much like the world it describes.', true, 0, 'MEDIUM', 5, 'The central event—Bunny''s murder—happens early, but the real suspense lies in watching the group unravel under the weight of their secret. The climax at the ravine and the final dissolution of the clique are particularly haunting.', '2026-04-15 20:49:09.790908', 1, 'A mesmerizing descent into obsession, beauty, and moral decay.', 'Lovers of dark academia, psychological thrillers, and character-driven literary fiction. If you enjoy morally ambiguous protagonists and immersive, slow-burn tension.', 'Readers seeking a fast-paced whodunit or clear-cut heroes. The characters are deeply flawed and often unlikable; the narrative is dense and introspective.');
  INSERT INTO public.reviews (id, book_id, created_at, detailed_review, has_spoiler, helpful_count, pacing, rating, spoiler_content, updated_at, user_id, verdict, who_is_it_for, who_is_it_not_for) VALUES (4, 3, '2026-04-18 20:12:21.011391', 'Tartt masterfully inverts the detective genre by revealing the murder on the first page, then spends the rest of the novel exploring the psychological aftermath. The prose is lush and intoxicating, much like the world it describes.', true, 0, 'MEDIUM', 5, 'The central event—Bunny''s murder—happens early, but the real suspense lies in watching the group unravel under the weight of their secret. The climax at the ravine and the final dissolution of the clique are particularly haunting.', '2026-04-18 20:12:21.011391', 2, 'A mesmerizing descent into obsession, beauty, and moral decay.', 'Lovers of dark academia, psychological thrillers, and character-driven literary fiction. If you enjoy morally ambiguous protagonists and immersive, slow-burn tension.', 'Readers seeking a fast-paced whodunit or clear-cut heroes. The characters are deeply flawed and often unlikable; the narrative is dense and introspective.');
  INSERT INTO public.reviews (id, book_id, created_at, detailed_review, has_spoiler, helpful_count, pacing, rating, spoiler_content, updated_at, user_id, verdict, who_is_it_for, who_is_it_not_for) VALUES (6, 4, '2026-04-18 20:26:08.072563', 'Bradbury distills an entire childhood summer into a series of interconnected vignettes, each one shimmering with wonder and melancholy. From the ritual of bottling dandelion wine to the terror of the Lonely One, every moment captures the heightened awareness of a boy discovering that joy and sorrow are two sides of the same coin. The prose is lyrical without being precious, and the Green Town setting feels both universal and deeply personal.', true, 0, 'MEDIUM', 5, 'The passing of Great-grandma, the revelation of the Lonely One''s true identity, and Douglas''s near-fatal illness all serve as poignant reminders that life''s sweetness is inseparable from its brevity.', '2026-04-18 20:26:08.072563', 3, 'A luminous, bittersweet celebration of summer, memory, and the fragile magic of being alive.', 'Anyone who has ever cherished a summer memory, smelled fresh-cut grass, or felt the pang of time passing. Perfect for readers seeking gentle, poetic fiction that finds the extraordinary in the ordinary.', 'Those who prefer plot-driven narratives or action-packed stories. This is a quiet, reflective book where the biggest event is often a new pair of tennis shoes or the purchase of a trolley ticket.');
  INSERT INTO public.reviews (id, book_id, created_at, detailed_review, has_spoiler, helpful_count, pacing, rating, spoiler_content, updated_at, user_id, verdict, who_is_it_for, who_is_it_not_for) VALUES (7, 4, '2026-04-18 20:32:06.826737', 'Bradbury distills an entire childhood summer into a series of interconnected vignettes, each one shimmering with wonder and melancholy. From the ritual of bottling dandelion wine to the terror of the Lonely One, every moment captures the heightened awareness of a boy discovering that joy and sorrow are two sides of the same coin. The prose is lyrical without being precious, and the Green Town setting feels both universal and deeply personal.', true, 0, 'MEDIUM', 5, 'The passing of Great-grandma, the revelation of the Lonely One''s true identity, and Douglas''s near-fatal illness all serve as poignant reminders that life''s sweetness is inseparable from its brevity.', '2026-04-18 20:32:06.826737', 4, 'A luminous, bittersweet celebration of summer, memory, and the fragile magic of being alive.', 'Anyone who has ever cherished a summer memory, smelled fresh-cut grass, or felt the pang of time passing. Perfect for readers seeking gentle, poetic fiction that finds the extraordinary in the ordinary.', 'Those who prefer plot-driven narratives or action-packed stories. This is a quiet, reflective book where the biggest event is often a new pair of tennis shoes or the purchase of a trolley ticket.');
  INSERT INTO public.reviews (id, book_id, created_at, detailed_review, has_spoiler, helpful_count, pacing, rating, spoiler_content, updated_at, user_id, verdict, who_is_it_for, who_is_it_not_for) VALUES (8, 5, '2026-04-18 20:34:43.25253', 'Tevis writes about chess with the precision and tension of a thriller. Beth Harmon is an unforgettable protagonist—gifted, damaged, and fiercely determined. The novel never glamorizes her addictions; instead, it shows how her genius and her demons are intertwined. The prose is spare and exact, mirroring the game itself, and the supporting cast—from the stoic janitor Mr. Shaibel to the enigmatic Benny Watts—adds depth without distracting from Beth''s solitary journey.', true, 0, 'MEDIUM', 4, 'Beth''s final match against Borgov in Moscow, her triumph without the aid of tranquilizers, and the quiet, redemptive return to the orphanage to honor Mr. Shaibel are the emotional climaxes of the story.', '2026-04-18 20:34:43.25253', 4, 'A taut, elegant novel about chess, compulsion, and the price of brilliance.', 'Fans of character-driven stories about obsession and mastery. You don''t need to know chess—the novel explains just enough to make the matches thrilling. Perfect for readers who enjoyed *The Goldfinch* or *A Beautiful Mind*.', 'Those seeking light entertainment or a romance subplot. The focus is squarely on Beth''s internal struggles and the chess world; relationships are secondary and often strained.');
  INSERT INTO public.reviews (id, book_id, created_at, detailed_review, has_spoiler, helpful_count, pacing, rating, spoiler_content, updated_at, user_id, verdict, who_is_it_for, who_is_it_not_for) VALUES (10, 4, '2026-04-23 12:31:23.652347', 'Bradbury’s prose is undeniably gorgeous — whole paragraphs read like poetry — and his ability to infuse everyday rituals with wonder is unmatched. The high points (the Happiness Machine, Mrs. Bentley’s lost letters) are profoundly moving. However, the episodic, almost plotless construction sometimes leaves the narrative feeling weightless; a few chapters read more like isolated sketches than parts of a cohesive whole. It’s a book to admire as much as to love, and its emotional resonance will depend entirely on your willingness to sink into its unhurried, reflective rhythm.', true, 0, 'SLOW', 4, 'Key episodes include the defeat of the ''Lonely One,'' the heartbreaking realization of the older woman that she has outlived her era, and the final bottling of summer itself. These moments shine brightest, though they are interspersed with more forgettable vignettes.', '2026-04-23 12:31:23.652347', 2, 'An exquisitely written, fragmentary portrait of a Midwestern summer that occasionally drifts too far into reverie.', 'Readers who value atmosphere and language over plot. Those with a fondness for memory pieces, Ray Bradbury’s softer side, or literary nostalgia. A great match for someone looking to savor each sentence.', 'Plot-driven readers, or those who become impatient with stories that prioritize mood over momentum. Some may find the lack of central conflict and the rose-tinted nostalgia a bit cloying after a while.');
  INSERT INTO public.reviews (id, book_id, created_at, detailed_review, has_spoiler, helpful_count, pacing, rating, spoiler_content, updated_at, user_id, verdict, who_is_it_for, who_is_it_not_for) VALUES (11, 8, '2026-04-23 15:00:41.394843', 'Shelley’s debut is nothing short of astonishing in its ambition and prescience. The central conceit—a man playing God and recoiling from his creation—raises timeless questions about responsibility, empathy, and what makes a monster. The creature’s first-person narrative is the novel’s heart, eloquent and devastating in its loneliness. Victor Frankenstein himself can be a frustratingly passive protagonist, wallowing in guilt rather than acting. Still, the icy dread of the final chase and the philosophical weight of the novel’s central tragedy make it an essential read, even if the emotional impact is sometimes blunted by the distance imposed by its structure.', false, 0, 'SLOW', 4, NULL, '2026-04-23 15:00:41.394843', 2, 'A revolutionary novel of ideas that gave birth to science fiction and remains deeply unsettling, though its sometimes overwrought prose distance the reader from its emotional core.', 'Lovers of classic literature, foundational science fiction, and Gothic horror. Ideal for those who enjoy grappling with moral ambiguity, the ethics of creation, and the nature of alienation.', 'Those who prefer fast-paced, visceral horror or tightly linear narratives. The 19th-century prose can feel dense, and Victor’s relentless passivity and self-pity may try the patience of readers seeking a more proactive hero.');
  INSERT INTO public.reviews (id, book_id, created_at, detailed_review, has_spoiler, helpful_count, pacing, rating, spoiler_content, updated_at, user_id, verdict, who_is_it_for, who_is_it_not_for) VALUES (12, 6, '2026-04-24 20:24:54.586401', 'R.F. Kuang has crafted something extraordinary—a novel that is at once a love letter to etymology, a searing indictment of colonialism, and a heartbreaking coming-of-age story set in the gilded halls of Oxford''s fictional Institute of Translation. The magic system, in which the nuances of language are harnessed to bend reality, is brilliantly inventive, and the footnotes that cradle the narrative add a scholarly weight that makes the world feel achingly real.', true, 0, 'MEDIUM', 5, 'The silver-working magic system relies on the untranslatable gaps between languages; the climax sees the Oxford tower itself turned into a weapon of mass liberation. The footnotes gradually reveal the deeper conspiracies of the British Empire, and the final sacrifice of Robin Swift is as heartbreaking as it is cathartic.', '2026-04-24 20:24:54.586401', 2, 'A magnificent, rage-filled symphony of language, power, and resistance that redefines dark academia.', 'Lovers of dark academia, linguistic puzzles, and anti-colonial literature. Anyone who values meticulous world-building, morally complex characters, and stories that make you think as much as feel. Perfect for fans of ''The Secret History'' and ''Jonathan Strange & Mr Norrell'', but with a righteous political edge.', 'Those seeking light escapism or fast-paced action. The novel is deliberately dense, scholarly, and builds toward a violent, tragic climax that may be too heavy for some. If you dislike extensive footnotes or stories where systemic injustice takes center stage, this might not be your cup of tea.');
  INSERT INTO public.reviews (id, book_id, created_at, detailed_review, has_spoiler, helpful_count, pacing, rating, spoiler_content, updated_at, user_id, verdict, who_is_it_for, who_is_it_not_for) VALUES (9, 3, NULL, 'Tartt masterfully inverts the detective genre by revealing the murder on the first page, then spends the rest of the novel exploring the psychological aftermath. The prose is lush and intoxicating, much like the world it describes.', true, 1, 'MEDIUM', 5, 'The central event—Bunny''s murder—happens early, but the real suspense lies in watching the group unravel under the weight of their secret. The climax at the ravine and the final dissolution of the clique are particularly haunting.', '2026-09-20 19:24:21.693614', 3, 'A mesmerizing descent into obsession, beauty, and moral decay.', 'Lovers of dark academia, psychological thrillers, and character-driven literary fiction. If you enjoy morally ambiguous protagonists and immersive, slow-burn tension.', 'Readers seeking a fast-paced whodunit or clear-cut heroes. The characters are deeply flawed and often unlikable; the narrative is dense and introspective.');
