  INSERT INTO public.reviews (id, book_id, created_at, detailed_review, has_spoiler, helpful_count, pacing, rating, spoiler_content, updated_at, user_id, verdict, who_is_it_for, who_is_it_not_for) VALUES (13, 19, NULL, 'M.L. Rio’s debut is a masterclass in atmosphere. It follows seven fourth-year theatre students at an elite conservatory, all typecast in their usual roles - both on stage and off. The narrative is framed as a confession from Oliver Marks to the detective who put him in prison a decade earlier, drawing the reader into a web of loyalty, jealousy, and a murder that may or may not have been an accident.
